create table if not exists public.sp_presentations(id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,title text not null default 'Untitled presentation',content jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index if not exists sp_presentations_owner_updated on public.sp_presentations(user_id,updated_at desc);alter table public.sp_presentations enable row level security;drop policy if exists sp_presentations_select_own on public.sp_presentations;create policy sp_presentations_select_own on public.sp_presentations for select to authenticated using(user_id=auth.uid());drop policy if exists sp_presentations_insert_own on public.sp_presentations;create policy sp_presentations_insert_own on public.sp_presentations for insert to authenticated with check(user_id=auth.uid());drop policy if exists sp_presentations_update_own on public.sp_presentations;create policy sp_presentations_update_own on public.sp_presentations for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());drop policy if exists sp_presentations_delete_own on public.sp_presentations;create policy sp_presentations_delete_own on public.sp_presentations for delete to authenticated using(user_id=auth.uid());grant select,insert,update,delete on public.sp_presentations to authenticated;